"""Local go2rtc control; provider URLs never leave this process."""

from __future__ import annotations

import hashlib
import json
import urllib.parse
import urllib.request
from urllib.error import HTTPError, URLError
from urllib.parse import urlsplit


class RestreamError(RuntimeError):
    """A secret-safe go2rtc operation failure."""


class Go2Rtc:
    def __init__(self, api_url: str = "http://127.0.0.1:1984") -> None:
        self.api_url = api_url.rstrip("/")

    def is_ready(self) -> bool:
        try:
            with urllib.request.urlopen(f"{self.api_url}/api", timeout=3) as response:
                return 200 <= response.status < 300
        except (HTTPError, URLError, TimeoutError, OSError):
            return False

    def replace_source(self, name: str, source: str) -> None:
        parts = urlsplit(source)
        if parts.scheme != "rtsp" or not parts.hostname:
            raise RestreamError("invalid source")
        query = urllib.parse.urlencode({"name": name, "src": source})
        for method in ("PATCH", "PUT"):
            request = urllib.request.Request(
                f"{self.api_url}/api/streams?{query}", method=method
            )
            try:
                with urllib.request.urlopen(request, timeout=10) as response:
                    if response.status < 200 or response.status >= 300:
                        raise RestreamError("go2rtc rejected source")
                    return
            except HTTPError as exc:
                if method == "PATCH" and exc.code == 404:
                    continue
                raise RestreamError("go2rtc rejected source") from None
            except (URLError, TimeoutError, OSError):
                raise RestreamError("go2rtc unavailable") from None
        raise RestreamError("go2rtc rejected source")

    def stream_status(self, name: str) -> bool:
        query = urllib.parse.urlencode({"src": name})
        try:
            with urllib.request.urlopen(
                f"{self.api_url}/api/streams?{query}", timeout=3
            ) as response:
                payload = json.loads(response.read())
        except (HTTPError, URLError, TimeoutError, OSError, json.JSONDecodeError):
            return False
        return isinstance(payload, dict)

    @staticmethod
    def stable_name(checkpoint_id: str) -> str:
        digest = hashlib.sha256(checkpoint_id.encode()).hexdigest()[:12]
        return f"md_parking_{digest}"
